SELECT CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, city, ROUND((100 * SUM(CASE WHEN country = 'JP' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_jp, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values FROM suppliers GROUP BY CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END, city HAVING ROUND((100 * SUM(CASE WHEN country = 'JP' THEN 1 ELSE 0 END)) / COUNT(*), 1) > 58
